function onNarrativeChanged(){ui.pending=null;refreshInjection();if(!backdrop.hidden&&ui.page!=='settings')render();}
function destroy(){ui.destroyed=true;ui.epoch++;stop();ui.rankController?.abort();ui.discoveryController?.abort();ui.injection?.uninject?.();for(const d of ui.disposers)d?.stop?.();host.removeEventListener('resize',viewport);host.visualViewport?.removeEventListener('resize',viewport);host.visualViewport?.removeEventListener('scroll',viewport);window.removeEventListener('pagehide',destroy);mount.remove();if(host.__TavernYouTubeStudio?.destroy===destroy)delete host.__TavernYouTubeStudio;}
