  const kind=select(f,'账号类型','personal',[['personal','个人创作者'],['group','乐队／组合']]),name=field(f,'账号名称',initial?(context()?.name2||''):''),category=field(f,'账号赛道','偶像'),subs=field(f,'初始粉丝量',0,'number'),date=field(f,'剧情日期','');
