const subscribe=resolve('eventOn'),events=window.tavern_events||host.tavern_events||{};
if(subscribe){
  const buttonEvent=resolve('getButtonEvent');if(buttonEvent)ui.disposers.push(subscribe(buttonEvent('YouTube'),open));
  for(const key of ['CHAT_CHANGED','MESSAGE_UPDATED','MESSAGE_DELETED','MESSAGE_SWIPED','MESSAGE_EDITED'])if(events[key])ui.disposers.push(subscribe(events[key],key==='CHAT_CHANGED'?onChatChanged:onNarrativeChanged));
  if(events.GENERATION_AFTER_COMMANDS)ui.disposers.push((resolve('eventMakeFirst')||subscribe)(events.GENERATION_AFTER_COMMANDS,refreshInjection));
  if(events.MESSAGE_RECEIVED)ui.disposers.push(subscribe(events.MESSAGE_RECEIVED,()=>{onNarrativeChanged();if(options().auto&&!ui.busy&&!chat().at(-1)?.is_user)run(()=>generateUpdate(true));}));
}
